		}
		Adjacencies.Remove(PortIndex);
		Ports.RemoveAt(PortIndex);
	}
	PortsToRemove.Empty();
	UE_LOG(LogTemp, Warning, TEXT("%i/%i ports are dirty afer PortsToRemove"), PortsDirty.Num(), Ports.Num());

